{"cards": [{"node_code": "N_e4eb3545e1e1eb87", "definition": "研究混凝土硬化后（成型并达到一定龄期）的力学、物理及耐久性指标测试方法、试验规程及质量评价标准的技术领域。", "boundary": "本节点聚焦于硬化混凝土实体，涵盖抗压、抗折、弹性模量等力学性能，以及抗渗、抗冻、碳化等耐久性指标的实验室测试。与“拌合物性能”的区别在于，本节点针对已凝固的固体材料，而非流动状态；与“组成材料”的区别在于，本节点测试的是混合后的整体性能，而非单一组分。", "includes": ["硬化混凝土抗压、抗折、劈裂抗拉及弹性模量等力学性能试验", "硬化混凝土抗渗、抗冻、抗氯离子渗透及碳化深度等耐久性试验", "硬化混凝土体积稳定性（如干缩、徐变）及物理性质测试"], "excludes": ["混凝土拌合物的工作性（坍落度、扩展度等）测试（归入拌合物性能）", "水泥、骨料、外加剂等单一原材料的检验试验（归入组成材料）", "混凝土结构构件的现场无损检测与结构安全鉴定（归入工程检测）"], "sibling_distinctions": [{"other_code": "N_3afd4a6dc0ad1e53", "rule": "本节点针对硬化后的固体混凝土；兄弟节点针对浇筑前流动状态的拌合物。"}, {"other_code": "N_de4296ab462c1ef6", "rule": "本节点测试混凝土整体性能；兄弟节点测试构成混凝土的单一原材料（如水泥、砂、石）性能。"}], "cross_boundary_rule": "若测试对象为成型试件或硬化块体，归本节点；若测试对象为未凝固的浆体或混合物，归入拌合物性能。"}, {"node_code": "N_de4296ab462c1ef6", "definition": "研究混凝土中各组成材料（水泥、骨料、水、外加剂、掺合料等）的常规检验方法、试验规程及质量评价标准的技术领域。", "boundary": "本节点聚焦于混凝土的“输入端”，即单一组分的性能验证。涵盖水泥强度与安定性、骨料级配与含泥量、外加剂减水率等测试。与“硬化混凝土性能”的区别在于，本节点不测试混合后的整体效应，而是确保各组分符合标准；与“拌合物性能”的区别在于，本节点针对未混合或单独存在的材料。", "includes": ["水泥的强度、凝结时间、安定性及细度等检验试验", "粗、细骨料的级配、含泥量、针片状含量及压碎值等检验试验", "外加剂、掺合料及拌合用水的常规性能检验试验"], "excludes": ["混凝土拌合物的工作性测试（归入拌合物性能）", "硬化混凝土的整体力学或耐久性测试（归入硬化混凝土性能）", "混凝土配合比设计理论及优化算法（归入材料性能或具体材料类别）"], "sibling_distinctions": [{"other_code": "N_e4eb3545e1e1eb87", "rule": "本节点测试单一组分（如水泥、砂）；兄弟节点测试由组分混合硬化后的整体混凝土。"}, {"other_code": "N_3afd4a6dc0ad1e53", "rule": "本节点测试未混合的原材料；兄弟节点测试已混合但未硬化的拌合物。"}], "cross_boundary_rule": "若测试对象为单一材料（如单独的水泥袋或一车石子），归本节点；若测试对象为混合后的浆体或硬化体，归入相应性能节点。"}, {"node_code": "N_3afd4a6dc0ad1e53", "definition": "研究混凝土拌合物（未硬化状态）的工作性、稳定性及基本物理指标测试方法、试验规程及质量评价标准的技术领域。", "boundary": "本节点聚焦于混凝土在浇筑前的流动状态，涵盖坍落度、扩展度、含气量、泌水率等测试。与“硬化混凝土性能”的区别在于，本节点针对可塑的浆体，而非固体；与“组成材料”的区别在于，本节点测试的是各组分混合后的整体表现，而非单一组分。", "includes": ["混凝土拌合物坍落度、坍落扩展度及维勃稠度等工作性试验", "混凝土拌合物含气量、泌水率及离析度等稳定性试验", "混凝土拌合物表观密度及温度等物理指标测试"], "excludes": ["硬化混凝土的力学或耐久性测试（归入硬化混凝土性能）", "水泥、骨料等单一原材料的检验试验（归入组成材料）", "混凝土配合比设计理论及优化算法（归入材料性能或具体材料类别）"], "sibling_distinctions": [{"other_code": "N_e4eb3545e1e1eb87", "rule": "本节点针对未硬化的流动拌合物；兄弟节点针对已硬化的固体混凝土。"}, {"other_code": "N_de4296ab462c1ef6", "rule": "本节点测试混合后的整体工作性；兄弟节点测试混合前的单一原材料性能。"}], "cross_boundary_rule": "若测试对象为可流动的浆体或混合物，归本节点；若测试对象为已凝固的固体，归入硬化混凝土性能。"}]}
